}

top.ComposeMessage(
  composeType,
  event?.shiftKey
    ? Ci.nsIMsgCompFormat.OppositeOfDefault
    : Ci.nsIMsgCompFormat.Default,
  msgFolder,
  msgUris,
  selection,
  autodetectCharset
);
